                            current_visited.add(nw)
                            layer[nw].add(word)
                            if nw == endWord:
                                found = True
            visited |= current_visited
            q = deque(current_visited)
        # DFS backtrack from endWord
        res = []
        def backtrack(word, path):
            if word == beginWord:
                res.append(path[::-1])
                return
            for prev in layer[word]:
                backtrack(prev, path + [prev])
        if found:
            backtrack(endWord, [endWord])
        return res

class Solution:
    def sumNumbers(self, root: TreeNode) -> int:
        def dfs(node, num):
            if not node:
                return 0
            num = num * 10 + node.val
            if not node.left and not node.right:
                return num
            return dfs(node.left, num) + dfs(node.right, num)
        return dfs(root, 0)

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        is_pal = [[False]*n for _ in range(n)]
        for i in range(n-1, -1, -1):
            for j in range(i, n):
                if s[i] == s[j] and (j - i <= 2 or is_pal[i+1][j-1]):
                    is_pal[i][j] = True
        dp = list(range(n))
        for i in range(1, n):
            if is_pal[0][i]:
                dp[i] = 0
            else:
                for j in range(1, i+1):
                    if is_pal[j][i]:
                        dp[i] = min(dp[i], dp[j-1]+1)
        return dp[n-1]

class Solution:
    def singleNumber(self, nums: list[int]) -> int:
        ones = twos = 0
        for n in nums:
            ones = (ones ^ n) & ~twos
            twos = (twos ^ n) & ~ones
        return ones

class Solution:
    def wordBreak(self, s: str, wordDict: list[str]) -> list[str]:
        from functools import lru_cache
        word_set = set(wordDict)
        @lru_cache(maxsize=None)
        def backtrack(start):
            if start == len(s):
                return ['']
            res = []
            for end in range(start+1, len(s)+1):
                word = s[start:end]
                if word in word_set:
                    for sub in backtrack(end):
                        res.append(word + (' ' + sub if sub else ''))
            return res
        return backtrack(0)

class Solution:
    def insertionSortList(self, head: ListNode) -> ListNode:
        dummy = ListNode(0)
        cur = head
        while cur:
            nxt = cur.next
            prev = dummy
            while prev.next and prev.next.val < cur.val:
                prev = prev.next
            cur.next = prev.next
            prev.next = cur
            cur = nxt
        return dummy.next

